insert into public.exercises (id, nome_pt, nome_en, grupo_muscular, padrao_movimento, nivel, tipo, equipamento, equipamento_detalhe, local, tier, como_fazer) values
  ('e1', 'Flexão de braço', 'Push-Up', 'Peito, tríceps, ombros', 'empurrar', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 1, 'Mãos no chão na largura dos ombros, corpo reto da cabeça aos calcanhares; desça até o peito quase tocar o chão e empurre de volta. Mantenha o abdômen firme para não deixar o quadril cair.'),
  ('e2', 'Flexão com pés elevados', 'Decline Push-Up', 'Peito (superior), ombros', 'empurrar', 'intermediario', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 1, 'Flexão com os pés apoiados num banco/sofá. Aumenta a carga e foca a parte superior do peito.'),
  ('e3', 'Agachamento livre', 'Bodyweight Squat', 'Quadríceps, glúteos', 'agachar', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 1, 'Pés na largura dos ombros; desça flexionando joelhos e quadril como se fosse sentar, peito ereto e calcanhares no chão, até as coxas ficarem paralelas. Suba empurrando o chão.'),
  ('e4', 'Abdominal (crunch)', 'Crunch', 'Abdômen', 'core', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 1, 'Deitado de costas, joelhos dobrados; eleve o tronco contraindo o abdômen sem puxar o pescoço, e desça devagar. O movimento é curto, da escápula.'),
  ('e5', 'Abdominal na polia', 'Cable Crunch', 'Abdômen', 'core', 'iniciante', 'forca_hipertrofia', 'academia', 'Polia', 'academia', 1, 'Ajoelhado na polia alta, corda atrás da cabeça, encurve o tronco contraindo o abdômen. Permite carga no abdominal.'),
  ('e6', 'Abdominal na máquina', 'Machine Crunch', 'Abdômen', 'core', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 1, 'Sentado, encurve o tronco contra a resistência. Permite carga progressiva no abdômen.'),
  ('e7', 'Prancha', 'Plank', 'Core (abdômen, lombar)', 'core', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 1, 'Apoie antebraços e pontas dos pés, corpo reto como uma tábua; segure a posição contraindo abdômen e glúteos. Não deixe o quadril subir nem cair.'),
  ('e8', 'Roda abdominal', 'Ab Wheel Rollout', 'Core', 'core', 'avancado', 'forca_hipertrofia', 'casa', 'Roda abdominal', 'casa_com', 1, 'Ajoelhado, role a roda à frente estendendo o corpo e volte usando o abdômen. Mantenha a lombar protegida; desafiador.'),
  ('e9', 'Supino reto', 'Bench Press', 'Peito, tríceps, ombros', 'empurrar', 'intermediario', 'forca_hipertrofia', 'academia', 'Barra / Halteres', 'academia', 1, 'Deitado no banco, desça a barra até o meio do peito e empurre para cima. Em casa, dá para fazer com halteres. Mantenha os punhos firmes e os ombros apoiados.'),
  ('e10', 'Supino inclinado', 'Incline Bench Press', 'Peito (superior), ombros, tríceps', 'empurrar', 'intermediario', 'forca_hipertrofia', 'academia', 'Barra / Halteres', 'academia', 1, 'Banco a ~30–45°; desça a barra até a parte alta do peito e empurre. Foca a porção superior do peitoral.'),
  ('e11', 'Supino com halteres', 'Dumbbell Bench Press', 'Peito, tríceps, ombros', 'empurrar', 'intermediario', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 1, 'Como o supino, mas com halteres: mais amplitude e estabilização. Ótimo para casa com um banco.'),
  ('e12', 'Supino inclinado com halteres', 'Incline Dumbbell Press', 'Peito (superior), ombros', 'empurrar', 'intermediario', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 1, 'Supino inclinado com halteres; mais amplitude que a barra. Boa opção de casa com banco ajustável.'),
  ('e13', 'Supino declinado', 'Decline Bench Press', 'Peito (inferior), tríceps', 'empurrar', 'intermediario', 'forca_hipertrofia', 'academia', 'Barra / Halteres', 'academia', 1, 'Banco declinado; desça a barra até a parte baixa do peito e empurre. Enfatiza a porção inferior.'),
  ('e14', 'Crucifixo na polia (cabos)', 'Cable Fly', 'Peito', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Polia', 'academia', 1, 'Em pé entre as polias na altura do peito, junte as mãos à frente apertando o peitoral. Tensão constante.'),
  ('e15', 'Supino na máquina', 'Machine Chest Press', 'Peito, tríceps', 'empurrar', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 1, 'Sentado, empurre as alavancas à frente e retorne. Versão guiada e segura do supino, boa para iniciantes.'),
  ('e16', 'Afundo (avanço)', 'Lunge', 'Quadríceps, glúteos', 'agachar', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 1, 'Dê um passo à frente e desça até o joelho de trás quase tocar o chão, tronco ereto; volte empurrando com a perna da frente. Joelho da frente alinhado com o pé.'),
  ('e17', 'Passada andando', 'Walking Lunge', 'Quadríceps, glúteos', 'agachar', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal / Halteres', 'casa_sem', 1, 'Afundos caminhando para a frente, alternando as pernas. Pode segurar halteres para mais carga.'),
  ('e18', 'Avanço lateral', 'Lateral Lunge', 'Quadríceps, glúteos, adutores', 'agachar', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 1, 'Passo amplo para o lado, flexione essa perna mantendo a outra estendida, e volte. Trabalha o plano lateral, pouco treinado.'),
  ('e19', 'Rosca direta', 'Biceps Curl', 'Bíceps', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Halteres / Barra', 'casa_com', 1, 'Em pé, cotovelos junto ao corpo; flexione levando o peso aos ombros e desça controlando. Sem balançar o tronco. Em casa, halteres ou até garrafas de água servem.'),
  ('e20', 'Rosca com elástico', 'Band Curl', 'Bíceps', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Elástico', 'casa_com', 1, 'Pise no elástico e faça a rosca. A resistência cresce no fim do movimento; ótimo para casa/viagem.'),
  ('e21', 'Barra fixa', 'Pull-Up', 'Costas, bíceps', 'puxar', 'avancado', 'forca_hipertrofia', 'casa', 'Barra fixa', 'casa_com', 1, 'Pendurado na barra com pegada pronada, puxe o corpo até o queixo passar a barra e desça controlando. Uma barra de porta resolve em casa; iniciantes podem usar elástico de auxílio.'),
  ('e22', 'Barra fixa supinada (chin-up)', 'Chin-Up', 'Costas, bíceps', 'puxar', 'intermediario', 'forca_hipertrofia', 'casa', 'Barra fixa', 'casa_com', 1, 'Barra fixa com pegada supinada (palmas para você). Recruta mais o bíceps e costuma ser mais fácil que a pronada.'),
  ('e23', 'Polichinelo', 'Jumping Jack', 'Corpo inteiro (cardio)', 'cardio', 'iniciante', 'cardio', 'nenhum', 'Peso corporal', 'casa_sem', 1, 'Salte abrindo pernas e levando os braços acima da cabeça, e volte. Ótimo para aquecer e elevar a frequência cardíaca.'),
  ('e24', 'Corrida na esteira', 'Treadmill', 'Cardio', 'cardio', 'iniciante', 'cardio', 'academia', 'Máquina', 'academia', 1, 'Caminhada ou corrida na esteira, ajustando velocidade e inclinação. O cardio mais comum da academia; correr ao ar livre substitui.'),
  ('e25', 'Polichinelo agachado', 'Squat Jack', 'Corpo inteiro (cardio)', 'cardio', 'iniciante', 'cardio', 'nenhum', 'Peso corporal', 'casa_sem', 1, 'Como o polichinelo, mas descendo num meio agachamento a cada abertura. Aumenta o trabalho de pernas.'),
  ('e26', 'Levantamento terra', 'Deadlift', 'Posterior de coxa, glúteos, lombar, costas', 'dobradica_quadril', 'avancado', 'forca_hipertrofia', 'academia', 'Barra / Halteres', 'academia', 1, 'Com a barra no chão, quadril para trás e coluna neutra, levante estendendo quadril e joelhos juntos. Um dos mais completos; exige técnica — comece leve.'),
  ('e27', 'Levantamento terra sumô', 'Sumo Deadlift', 'Glúteos, adutores, posterior', 'dobradica_quadril', 'avancado', 'forca_hipertrofia', 'academia', 'Barra', 'academia', 1, 'Terra com pés bem afastados e mãos por dentro das pernas. Recruta mais glúteos e parte interna da coxa.'),
  ('e28', 'Leg press', 'Leg Press', 'Quadríceps, glúteos', 'agachar', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 1, 'Sentado na máquina, empurre a plataforma estendendo as pernas sem travar os joelhos e retorne controlando. Bom para iniciantes por ser guiado.'),
  ('e29', 'Bicicleta ergométrica', 'Stationary Bike', 'Cardio, pernas', 'cardio', 'iniciante', 'cardio', 'academia', 'Máquina', 'academia', 1, 'Pedale ajustando a resistência. Cardio de baixo impacto, bom para as articulações.'),
  ('e30', 'Burpee', 'Burpee', 'Corpo inteiro (cardio)', 'cardio', 'intermediario', 'cardio', 'nenhum', 'Peso corporal', 'casa_sem', 1, 'Agache, apoie as mãos, jogue os pés para trás (posição de flexão), volte e salte para cima. Intenso; pode ser feito sem o salto para reduzir o impacto.'),
  ('e31', 'Elíptico', 'Elliptical', 'Cardio', 'cardio', 'iniciante', 'cardio', 'academia', 'Máquina', 'academia', 2, 'Movimento de passada no aparelho elíptico. Cardio de baixíssimo impacto, suave para os joelhos.'),
  ('e32', 'Agachamento com barra', 'Back Squat', 'Quadríceps, glúteos', 'agachar', 'intermediario', 'forca_hipertrofia', 'academia', 'Barra', 'academia', 2, 'Barra apoiada nas costas (trapézio); agache mantendo o tronco firme e suba. É a versão com carga do agachamento livre.'),
  ('e33', 'Agachamento goblet', 'Goblet Squat', 'Quadríceps, glúteos', 'agachar', 'iniciante', 'forca_hipertrofia', 'casa', 'Halter / Kettlebell', 'casa_com', 2, 'Segure um halter junto ao peito e agache. Ajuda a manter o tronco ereto — ótimo para aprender o agachamento com carga.'),
  ('e34', 'Agachamento no Smith', 'Smith Machine Squat', 'Quadríceps, glúteos', 'agachar', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina (Smith)', 'academia', 2, 'Agachamento na barra guiada. Mais estável, bom para focar as pernas com segurança ou treinar sozinho.'),
  ('e35', 'Escalador (mountain climber)', 'Mountain Climber', 'Core, cardio', 'cardio', 'iniciante', 'cardio', 'nenhum', 'Peso corporal', 'casa_sem', 2, 'Em posição de prancha alta, traga um joelho ao peito alternando rápido, como se corresse no lugar. Mantenha o quadril estável.'),
  ('e36', 'Elevação de panturrilha', 'Calf Raise', 'Panturrilhas', 'isolado', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 2, 'Em pé, eleve os calcanhares ficando na ponta dos pés, segure um instante e desça devagar. Pode usar um degrau para mais amplitude ou peso para mais carga.'),
  ('e37', 'Panturrilha unilateral', 'Single-Leg Calf Raise', 'Panturrilhas', 'isolado', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 2, 'Elevação de panturrilha apoiado numa perna só, com a mão na parede para equilíbrio. Dobra a carga sobre cada panturrilha sem precisar de peso; use um degrau para mais amplitude.'),
  ('e38', 'Panturrilha em pé (máquina)', 'Standing Calf Raise', 'Panturrilhas (gastrocnêmio)', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 2, 'Ombros sob o apoio, eleve os calcanhares e desça com amplitude total. Foca a parte externa da panturrilha.'),
  ('e39', 'Panturrilha no leg press', 'Calf Press', 'Panturrilhas', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 2, 'No leg press, empurre a plataforma só com a ponta dos pés, elevando e descendo os calcanhares.'),
  ('e40', 'Mergulho no banco (tríceps)', 'Bench Dips', 'Tríceps', 'empurrar', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 2, 'Mãos numa cadeira/banco atrás do corpo, desça flexionando os cotovelos e empurre de volta. Quanto mais à frente os pés, mais difícil.'),
  ('e41', 'Desenvolvimento de ombros', 'Overhead Press', 'Ombros, tríceps', 'empurrar', 'intermediario', 'forca_hipertrofia', 'casa', 'Halteres / Barra', 'casa_com', 2, 'Sentado ou em pé, empurre o peso acima da cabeça e desça até a linha dos ombros. Não arqueie demais a lombar. Halteres em casa funcionam bem.'),
  ('e42', 'Desenvolvimento com halteres (sentado)', 'Seated Dumbbell Press', 'Ombros, tríceps', 'empurrar', 'intermediario', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 2, 'Sentado com apoio nas costas, empurre os halteres acima da cabeça e desça à linha dos ombros. Estável e seguro.'),
  ('e43', 'Desenvolvimento na máquina', 'Machine Shoulder Press', 'Ombros, tríceps', 'empurrar', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 2, 'Sentado, empurre as alavancas para cima e retorne. Versão guiada do desenvolvimento.'),
  ('e44', 'Desenvolvimento com elástico', 'Band Overhead Press', 'Ombros', 'empurrar', 'iniciante', 'forca_hipertrofia', 'casa', 'Elástico', 'casa_com', 2, 'Pise no elástico e empurre as alças acima da cabeça. Desenvolvimento de ombros sem peso.'),
  ('e45', 'Remada curvada', 'Bent-Over Row', 'Costas, bíceps', 'puxar', 'intermediario', 'forca_hipertrofia', 'casa', 'Barra / Halteres', 'casa_com', 2, 'Tronco inclinado à frente com coluna neutra; puxe o peso em direção ao abdômen e desça. Em casa, com halteres; na academia, com barra.'),
  ('e46', 'Remada baixa (na polia)', 'Seated Cable Row', 'Costas, bíceps', 'puxar', 'iniciante', 'forca_hipertrofia', 'academia', 'Polia', 'academia', 2, 'Sentado, puxe o triângulo da polia ao abdômen apertando as escápulas e retorne. Base de qualquer treino de costas.'),
  ('e47', 'Remada na máquina', 'Machine Row', 'Costas, bíceps', 'puxar', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 2, 'Peito apoiado, puxe as alavancas para trás apertando as costas. Guiada e segura para a lombar.'),
  ('e48', 'Remada no Smith', 'Smith Machine Row', 'Costas', 'puxar', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina (Smith)', 'academia', 2, 'Remada curvada na barra guiada do Smith. Mais estável para focar as costas.'),
  ('e49', 'Puxada alta (pulldown)', 'Lat Pulldown', 'Costas (dorsais)', 'puxar', 'iniciante', 'forca_hipertrofia', 'academia', 'Polia / Máquina', 'academia', 2, 'Sentado, puxe a barra da polia até a altura do peito contraindo as costas, e retorne controlando. Alternativa guiada à barra fixa.'),
  ('e50', 'Puxada triângulo (pegada fechada)', 'Close-Grip Pulldown', 'Costas (dorsais)', 'puxar', 'iniciante', 'forca_hipertrofia', 'academia', 'Polia / Máquina', 'academia', 2, 'Puxada com triângulo, focando a parte central e baixa das costas. Puxe até o peito e controle a volta.'),
  ('e51', 'Puxada unilateral na polia', 'Single-Arm Pulldown', 'Costas (dorsais)', 'puxar', 'intermediario', 'forca_hipertrofia', 'academia', 'Polia', 'academia', 2, 'Puxada um braço por vez na polia alta. Corrige diferenças entre os lados e dá mais amplitude.'),
  ('e52', 'Elevação lateral', 'Lateral Raise', 'Ombros (lateral)', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 2, 'Em pé, eleve os halteres pelos lados até a altura dos ombros, cotovelos levemente flexionados, e desça devagar. Movimento leve e controlado.'),
  ('e53', 'Elevação lateral na polia', 'Cable Lateral Raise', 'Ombros (lateral)', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Polia', 'academia', 2, 'Elevação lateral na polia baixa, um braço por vez. Tensão constante no deltoide lateral.'),
  ('e54', 'Elevação lateral deitado', 'Lying Lateral Raise', 'Ombros (lateral)', 'isolado', 'intermediario', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 2, 'Deitado de lado, eleve o halter pela lateral. Foca o deltoide lateral com uma tensão diferente.'),
  ('e55', 'Crucifixo', 'Chest Fly', 'Peito', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 2, 'Deitado num banco com halteres acima do peito e os cotovelos levemente flexionados, abra os braços em arco até alongar o peito e feche apertando o peitoral. (A versão em máquina é o Voador/peck deck.)'),
  ('e56', 'Crucifixo inclinado', 'Incline Dumbbell Fly', 'Peito (superior)', 'isolado', 'intermediario', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 2, 'Crucifixo no banco inclinado, focando a parte de cima do peito. Braços semiflexionados, abra e feche em arco.'),
  ('e57', 'Ponte de glúteo', 'Glute Bridge', 'Glúteos, posterior de coxa', 'dobradica_quadril', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 2, 'Deitado de costas, joelhos dobrados, eleve o quadril contraindo os glúteos até o corpo formar uma linha dos joelhos aos ombros, e desça. Pode pôr peso sobre o quadril.'),
  ('e58', 'Ponte de glúteo com pés elevados', 'Feet-Elevated Glute Bridge', 'Glúteos, posterior de coxa', 'dobradica_quadril', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 2, 'Faça a ponte com os pés apoiados num banco/sofá em vez do chão. Aumenta a amplitude e o trabalho de glúteo e posterior; dá para fazer numa perna só para intensificar.'),
  ('e59', 'Elevação de quadril (hip thrust)', 'Hip Thrust', 'Glúteos', 'dobradica_quadril', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal (apoio no sofá)', 'casa_sem', 2, 'Sente no chão com as costas apoiadas na borda do sofá/cama e os pés firmes no chão; eleve o quadril até o tronco ficar paralelo ao chão, apertando os glúteos no topo, e desça. Em casa o peso do corpo já funciona — dá para abraçar um objeto pesado sobre o quadril para progredir.'),
  ('e60', 'Coice de glúteo na polia', 'Cable Glute Kickback', 'Glúteos', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Polia / Elástico', 'academia', 2, 'Tornozelo preso à polia baixa, estenda a perna para trás contraindo o glúteo. Em casa, com elástico.'),
  ('e61', 'Afundo com halteres', 'Dumbbell Lunge', 'Quadríceps, glúteos', 'agachar', 'intermediario', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 2, 'Afundo segurando halteres ao lado do corpo. Aumenta a carga do afundo tradicional.'),
  ('e62', 'Cadeira extensora', 'Leg Extension', 'Quadríceps', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 2, 'Sentado na máquina, estenda as pernas até quase travar os joelhos e retorne controlando. Isolamento do quadríceps.'),
  ('e63', 'Cadeira extensora unilateral', 'Single-Leg Extension', 'Quadríceps', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 2, 'Extensora uma perna por vez. Corrige assimetrias entre as pernas.'),
  ('e64', 'Mesa flexora', 'Leg Curl', 'Posterior de coxa', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 2, 'Deitado ou sentado na máquina, flexione os joelhos puxando o apoio e retorne devagar. Isolamento dos posteriores.'),
  ('e65', 'Mesa flexora sentada', 'Seated Leg Curl', 'Posterior de coxa', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 2, 'Sentado na máquina, flexione os joelhos puxando o apoio para baixo e retorne controlando. A posição sentada alonga mais o posterior que a versão deitada; ótimo isolador.'),
  ('e66', 'Cadeira flexora em pé', 'Standing Leg Curl', 'Posterior de coxa', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 2, 'Em pé na máquina, flexione um joelho por vez. Isola o posterior de coxa unilateralmente.'),
  ('e67', 'Tríceps testa', 'Skull Crusher', 'Tríceps', 'isolado', 'intermediario', 'forca_hipertrofia', 'casa', 'Halteres / Barra', 'casa_com', 2, 'Deitado, braços para cima, flexione só os cotovelos descendo o peso até perto da testa e estenda. Cotovelos apontando ao teto, sem abrir.'),
  ('e68', 'Tríceps na polia', 'Triceps Pushdown', 'Tríceps', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Polia', 'academia', 2, 'Em pé na polia alta, estenda os cotovelos empurrando a barra para baixo e retorne. Cotovelos colados ao corpo.'),
  ('e69', 'Tríceps na corda', 'Rope Pushdown', 'Tríceps', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Polia', 'academia', 2, 'Tríceps na polia com a corda, abrindo as pontas no fim. Variação muito usada do tríceps pulley.'),
  ('e70', 'Supino fechado', 'Close-Grip Bench Press', 'Tríceps, peito', 'empurrar', 'intermediario', 'forca_hipertrofia', 'academia', 'Barra', 'academia', 2, 'Supino com pegada na largura dos ombros, focando o tríceps. Cotovelos mais próximos do corpo.'),
  ('e71', 'Tríceps testa na polia', 'Cable Skull Crusher', 'Tríceps', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Polia', 'academia', 3, 'Tríceps testa feito na polia. Tensão constante; poupa o cotovelo.'),
  ('e72', 'Rosca martelo', 'Hammer Curl', 'Bíceps, antebraço', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 3, 'Como a rosca direta, mas com os halteres na vertical (pegada neutra, polegar para cima). Trabalha mais o antebraço.'),
  ('e73', 'Rosca inversa', 'Reverse Curl', 'Antebraços, bíceps', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Halteres / Barra', 'casa_com', 3, 'Rosca com as palmas voltadas para baixo (pegada pronada), subindo o peso até os ombros. Foca a parte de cima do antebraço e o braquiorradial.'),
  ('e74', 'Rosca concentrada', 'Concentration Curl', 'Bíceps', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Halter', 'casa_com', 3, 'Sentado, cotovelo apoiado na coxa, faça a rosca isolando o bíceps. Excelente para o pico do bíceps.'),
  ('e75', 'Rosca na polia', 'Cable Curl', 'Bíceps', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Polia', 'academia', 3, 'Rosca em pé na polia baixa. Tensão constante do início ao fim do movimento.'),
  ('e76', 'Rosca inclinada', 'Incline Dumbbell Curl', 'Bíceps', 'isolado', 'intermediario', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 3, 'Sentado num banco inclinado, braços pendurados, faça a rosca. Alonga mais o bíceps no início.'),
  ('e77', 'Rosca martelo na corda', 'Rope Hammer Curl', 'Bíceps, antebraço', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Polia', 'academia', 3, 'Rosca com a corda na polia, pegada neutra. Trabalha bíceps e antebraço com tensão constante.'),
  ('e78', 'Agachamento búlgaro', 'Bulgarian Split Squat', 'Quadríceps, glúteos', 'agachar', 'intermediario', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 3, 'Pé de trás apoiado num banco/sofá, desça flexionando a perna da frente e suba. Exige equilíbrio; ótimo unilateral. Pode segurar halteres.'),
  ('e79', 'Afundo no Smith', 'Smith Split Squat', 'Quadríceps, glúteos', 'agachar', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina (Smith)', 'academia', 3, 'Búlgaro/afundo na barra guiada. Mais estável para carregar com segurança.'),
  ('e80', 'Stiff (terra romeno)', 'Romanian Deadlift', 'Posterior de coxa, glúteos', 'dobradica_quadril', 'intermediario', 'forca_hipertrofia', 'casa', 'Barra / Halteres', 'casa_com', 3, 'Joelhos levemente flexionados, leve o quadril para trás descendo o peso rente às pernas e suba. Sente o alongamento atrás da coxa; coluna neutra.'),
  ('e81', 'Stiff com halteres', 'Dumbbell Romanian Deadlift', 'Posterior de coxa, glúteos', 'dobradica_quadril', 'intermediario', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 3, 'Em pé com halteres à frente das coxas, leve o quadril para trás descendo os pesos rente às pernas (joelhos quase retos) até alongar o posterior; volte apertando os glúteos. Excelente opção de casa.'),
  ('e82', 'Stiff unilateral', 'Single-Leg Romanian Deadlift', 'Posterior de coxa, glúteos', 'dobradica_quadril', 'intermediario', 'forca_hipertrofia', 'casa', 'Halteres / Peso corporal', 'casa_com', 3, 'Apoiado numa perna só, leve o quadril para trás descendo o peso enquanto a outra perna estende atrás, formando uma linha. Trabalha posterior, glúteo e equilíbrio, e corrige diferenças entre os lados.'),
  ('e83', 'Flexão nórdica', 'Nordic Hamstring Curl', 'Posterior de coxa', 'dobradica_quadril', 'avancado', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 3, 'Ajoelhado com os pés presos sob o sofá (ou alguém segurando), desça o tronco à frente o mais devagar possível resistindo com o posterior, e empurre o chão com as mãos para voltar. Um dos mais potentes — e difíceis.'),
  ('e84', 'Remada unilateral (serrote)', 'One-Arm Dumbbell Row', 'Costas, bíceps', 'puxar', 'iniciante', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 3, 'Apoie joelho e mão num banco, puxe o halter ao lado do tronco e desça. Um braço por vez, costas paralelas ao chão.'),
  ('e85', 'Elevação de pernas', 'Leg Raise', 'Abdômen inferior', 'core', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 3, 'Deitado de costas, pernas estendidas, eleve-as até cerca de 90° e desça sem encostar no chão. Mãos sob o quadril protegem a lombar.'),
  ('e86', 'Curl de posterior deslizante', 'Sliding Leg Curl', 'Posterior de coxa', 'isolado', 'intermediario', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 3, 'Deitado em ponte com os pés sobre toalhas num piso liso, estenda e recolha as pernas deslizando enquanto mantém o quadril no alto. Simula a mesa flexora sem nenhum equipamento.'),
  ('e87', 'Mesa flexora com elástico', 'Banded Leg Curl', 'Posterior de coxa', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Elástico', 'casa_com', 3, 'Deitado de bruços com uma faixa elástica presa nos tornozelos e ancorada atrás, flexione os joelhos trazendo os calcanhares aos glúteos contra a resistência. Versão caseira do isolador de posterior.'),
  ('e88', 'Elevação de pernas suspenso', 'Hanging Leg Raise', 'Abdômen inferior', 'core', 'avancado', 'forca_hipertrofia', 'casa', 'Barra fixa', 'casa_com', 3, 'Pendurado na barra, eleve as pernas (ou joelhos) à frente e desça controlando. Comece com joelhos dobrados.'),
  ('e89', 'Elevação de joelhos no apoio', 'Captain''s Chair Knee Raise', 'Abdômen inferior', 'core', 'intermediario', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 3, 'Apoiado nos antebraços na cadeira romana, eleve os joelhos ao peito. Isola o abdômen inferior com segurança.'),
  ('e90', 'Prancha lateral', 'Side Plank', 'Core (oblíquos)', 'core', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 3, 'Apoiado num antebraço, corpo de lado em linha reta, quadril elevado; segure. Faça os dois lados. Trabalha a lateral do abdômen.'),
  ('e91', 'Prancha lateral com rotação', 'Side Plank Rotation', 'Core (oblíquos)', 'core', 'intermediario', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 3, 'Na prancha lateral, gire o braço de cima por baixo do tronco e volte. Dinamiza a prancha lateral.'),
  ('e92', 'Pular corda', 'Jump Rope', 'Corpo inteiro (cardio)', 'cardio', 'iniciante', 'cardio', 'casa', 'Corda', 'casa_com', 3, 'Saltos curtos girando a corda com os punhos; ótimo cardio de baixo custo. Aterrissar suave na ponta dos pés.'),
  ('e93', 'Remo (máquina)', 'Rowing Machine', 'Cardio, costas, pernas', 'cardio', 'iniciante', 'cardio', 'academia', 'Máquina', 'academia', 3, 'Puxe o cabo com pernas e costas num movimento contínuo. Cardio de corpo inteiro com baixo impacto.'),
  ('e94', 'Agachamento na parede (isométrico)', 'Wall Sit', 'Quadríceps', 'agachar', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 3, 'Costas na parede, desça até as coxas ficarem paralelas (como sentado numa cadeira invisível) e segure. Joelhos a 90°.'),
  ('e95', 'Remada alta', 'Upright Row', 'Ombros, trapézio', 'puxar', 'intermediario', 'forca_hipertrofia', 'casa', 'Halteres / Barra', 'casa_com', 3, 'Em pé, puxe o peso para cima rente ao corpo até a altura do peito, cotovelos liderando, e desça. Movimento moderado para poupar o ombro.'),
  ('e96', 'Remada alta com elástico', 'Band Upright Row', 'Ombros, trapézio', 'puxar', 'iniciante', 'forca_hipertrofia', 'casa', 'Elástico', 'casa_com', 3, 'Pise no elástico e puxe as alças para cima rente ao corpo até o peito. Alternativa portátil da remada alta.'),
  ('e97', 'Encolhimento (trapézio)', 'Shrug', 'Trapézio', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Halteres / Barra', 'casa_com', 3, 'Em pé com o peso nas mãos, eleve só os ombros em direção às orelhas e desça. Sem girar os ombros.'),
  ('e98', 'Elevação frontal', 'Front Raise', 'Ombros (anterior)', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 3, 'Em pé, eleve os halteres à frente até a altura dos ombros e desça controlando. Um de cada vez ou juntos.'),
  ('e99', 'Elevação frontal na polia', 'Cable Front Raise', 'Ombros (anterior)', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Polia', 'academia', 3, 'Elevação frontal na polia baixa. Tensão constante no deltoide anterior.'),
  ('e100', 'Paralelas (mergulho)', 'Dips', 'Peito, tríceps', 'empurrar', 'avancado', 'forca_hipertrofia', 'nenhum', 'Peso corporal (2 cadeiras firmes)', 'casa_sem', 3, 'Apoie as mãos em dois pontos firmes na mesma altura (duas cadeiras resistentes servem) com o corpo suspenso; desça flexionando os cotovelos até alongar o peito/tríceps e empurre de volta. Incline o tronco à frente para focar o peito; mantenha-o ereto para o tríceps.'),
  ('e101', 'Giro russo', 'Russian Twist', 'Core (oblíquos)', 'core', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 3, 'Sentado, tronco inclinado para trás e pés elevados, gire o tronco tocando o chão dos dois lados. Pode segurar um peso para dificultar.'),
  ('e102', 'Flexão lateral (oblíquo)', 'Dumbbell Side Bend', 'Core (oblíquos)', 'core', 'iniciante', 'forca_hipertrofia', 'casa', 'Halter', 'casa_com', 3, 'Em pé com um halter de um lado, incline o tronco lateralmente e volte. Trabalha os oblíquos.'),
  ('e103', 'Superman (extensão lombar)', 'Superman', 'Lombar, glúteos', 'dobradica_quadril', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 3, 'Deitado de bruços, eleve braços e pernas ao mesmo tempo contraindo a lombar e os glúteos, e desça. Movimento suave, sem forçar o pescoço.'),
  ('e104', 'Hiperextensão lombar', 'Back Extension', 'Lombar, glúteos', 'dobradica_quadril', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina / Peso corporal', 'academia', 3, 'No banco romano, desça o tronco e suba até alinhar com as pernas, sem hiperestender. Em casa, o superman substitui.'),
  ('e105', 'Subida no banco (step-up)', 'Step-Up', 'Quadríceps, glúteos', 'agachar', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 3, 'Suba com um pé num banco/degrau firme e desça controlando; alterne as pernas. Pode segurar halteres. Bom unilateral e funcional.'),
  ('e106', 'Crucifixo invertido', 'Reverse Fly', 'Ombros (posterior), costas', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 3, 'Tronco inclinado à frente, abra os halteres pelos lados apertando as escápulas e desça. Trabalha a parte de trás do ombro.'),
  ('e107', 'Crucifixo invertido na máquina', 'Reverse Pec Deck', 'Ombros (posterior)', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 3, 'Sentado de frente para a máquina, abra os braços para trás. Isola o deltoide posterior.'),
  ('e108', 'Balanço com kettlebell (swing)', 'Kettlebell Swing', 'Glúteos, posterior, core', 'dobradica_quadril', 'intermediario', 'forca_hipertrofia', 'casa', 'Kettlebell', 'casa_com', 3, 'Quadril para trás e impulsione o kettlebell à frente com a força do quadril (não dos braços), até a altura do peito. Explosivo e ótimo para condicionamento.'),
  ('e109', 'Caminhada do fazendeiro', 'Farmer''s Walk', 'Corpo inteiro, pegada, core', 'cardio', 'iniciante', 'cardio', 'casa', 'Halteres / Kettlebell', 'casa_com', 3, 'Caminhe segurando peso pesado em cada mão, tronco ereto. Fortalece pegada, trapézio e core de forma funcional.'),
  ('e110', 'Corda naval (battle rope)', 'Battle Ropes', 'Corpo inteiro, cardio', 'cardio', 'intermediario', 'cardio', 'academia', 'Cordas navais', 'academia', 3, 'Faça ondas com as cordas pesadas alternando os braços. Cardio intenso com trabalho de ombros e core.'),
  ('e111', 'Desenvolvimento Arnold', 'Arnold Press', 'Ombros', 'empurrar', 'intermediario', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 3, 'Desenvolvimento em que você gira os punhos da frente para fora ao subir. Recruta mais o ombro inteiro.'),
  ('e112', 'Rosca alternada', 'Alternating Curl', 'Bíceps', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 3, 'Rosca direta feita um braço de cada vez, alternando. Permite mais concentração em cada lado.'),
  ('e113', 'Flexão diamante', 'Diamond Push-Up', 'Tríceps, peito', 'empurrar', 'intermediario', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 3, 'Flexão com as mãos juntas formando um losango sob o peito. Foca mais o tríceps; mais difícil que a flexão comum.'),
  ('e114', 'Flexão pique (pike)', 'Pike Push-Up', 'Ombros', 'empurrar', 'avancado', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 3, 'Em ''V'' invertido (quadril alto), flexione os cotovelos levando a cabeça ao chão e empurre. Versão sem equipamento do desenvolvimento de ombros.'),
  ('e115', 'Abdominal infra (canivete)', 'V-Up', 'Abdômen', 'core', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 3, 'Deitado, eleve tronco e pernas ao mesmo tempo tentando tocar as mãos nos pés, formando um ''V'', e retorne controlando.'),
  ('e116', 'Remada invertida (na mesa)', 'Inverted Row', 'Costas, bíceps', 'puxar', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal (mesa firme)', 'casa_sem', 4, 'Deite sob uma mesa firme e segure a borda com as mãos; com o corpo reto e os calcanhares no chão, puxe o peito em direção à mesa apertando as costas e desça controlando. Quanto mais horizontal o corpo, mais difícil.'),
  ('e117', 'Bom dia (good morning)', 'Good Morning', 'Posterior de coxa, lombar', 'dobradica_quadril', 'avancado', 'forca_hipertrofia', 'academia', 'Barra', 'academia', 4, 'Barra nas costas, leve o quadril para trás inclinando o tronco à frente com coluna neutra e volte. Sente o posterior; faça leve.'),
  ('e118', 'Pendura na barra', 'Dead Hang', 'Antebraços', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Barra fixa', 'casa_com', 4, 'Pendure-se na barra com os braços estendidos pelo máximo de tempo que aguentar. Fortalece a pegada e o antebraço e ainda descomprime a coluna; uma barra de porta serve.'),
  ('e119', 'Puxada para o rosto (face pull)', 'Face Pull', 'Ombros (posterior), trapézio', 'puxar', 'iniciante', 'forca_hipertrofia', 'casa', 'Elástico', 'casa_com', 4, 'Com um elástico preso à frente na altura do rosto, puxe as mãos em direção à testa abrindo os cotovelos para fora e apertando a parte de trás dos ombros. Fortalece o deltoide posterior e ajuda na postura. Na academia, é feito na polia.'),
  ('e120', 'Puxada com elástico', 'Band Lat Pulldown', 'Costas (dorsais)', 'puxar', 'iniciante', 'forca_hipertrofia', 'casa', 'Elástico', 'casa_com', 4, 'Prenda o elástico no alto e puxe para baixo até o peito abrindo os cotovelos. Simula a puxada alta em casa.'),
  ('e121', 'Agachamento frontal', 'Front Squat', 'Quadríceps, core', 'agachar', 'intermediario', 'forca_hipertrofia', 'academia', 'Barra', 'academia', 4, 'Agachamento com a barra apoiada à frente (nos ombros). Mantém o tronco mais ereto e exige mais do quadríceps e do core.'),
  ('e122', 'Rosca scott', 'Preacher Curl', 'Bíceps', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Barra W ou halteres + banco Scott', 'academia', 4, 'Braços apoiados no banco Scott, faça a rosca com uma barra W ou halteres, sem impulso do corpo. O apoio elimina a ajuda dos ombros e isola o bíceps. (A versão em aparelho é a Rosca scott na máquina.)'),
  ('e123', 'Flexora no banco romano (glute-ham raise)', 'Glute-Ham Raise', 'Posterior de coxa, glúteos', 'dobradica_quadril', 'avancado', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 4, 'No aparelho de GHR, com os pés fixos, desça e suba o tronco usando posterior e glúteos. Avançado e muito eficiente para toda a cadeia posterior.'),
  ('e124', 'Rosca scott na máquina', 'Machine Preacher Curl', 'Bíceps', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 4, 'Rosca scott em máquina específica. Isola o bíceps e é fácil de progredir a carga.'),
  ('e125', 'Pullover', 'Pullover', 'Peito, dorsais', 'isolado', 'intermediario', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 4, 'Deitado, leve o halter atrás da cabeça com os braços quase estendidos e traga de volta sobre o peito. Alonga a caixa torácica.'),
  ('e126', 'Pullover na polia', 'Cable Pullover', 'Dorsais, peito', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Polia', 'academia', 4, 'Em pé na polia alta, braços quase estendidos, puxe a barra para baixo num arco. Isola o dorsal.'),
  ('e127', 'Cadeira abdutora', 'Hip Abduction', 'Glúteo médio, abdutores', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 4, 'Sentado na máquina, abra as pernas contra a resistência e retorne. Foca a lateral do glúteo. Em casa, dá para usar elástico.'),
  ('e128', 'Abdução de quadril na polia', 'Cable Hip Abduction', 'Glúteo médio', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Polia / Elástico', 'academia', 4, 'Em pé, afaste a perna lateralmente contra a polia/elástico. Trabalha a lateral do glúteo e a estabilidade do quadril.'),
  ('e129', 'Cadeira adutora', 'Hip Adduction', 'Adutores (parte interna da coxa)', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 4, 'Sentado na máquina, feche as pernas contra a resistência e retorne. Trabalha a parte interna da coxa.'),
  ('e130', 'Voador (peck deck)', 'Machine Fly', 'Peito', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 4, 'Sentado na máquina, junte os braços à frente apertando o peito e retorne controlando. Versão guiada do crucifixo.'),
  ('e131', 'Crossover (cabo cruzado)', 'Cable Crossover', 'Peito', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Polia', 'academia', 4, 'Em pé entre duas polias altas, cruze as mãos à frente do corpo apertando o peito e retorne. Boa tensão constante.'),
  ('e132', 'Crossover na polia baixa', 'Low Cable Crossover', 'Peito (superior)', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Polia', 'academia', 4, 'Cabos nas polias baixas; junte as mãos à frente e para cima. Foca a parte superior do peito.'),
  ('e133', 'Tríceps coice', 'Triceps Kickback', 'Tríceps', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 4, 'Tronco inclinado, cotovelo junto ao corpo, estenda o antebraço para trás e retorne. Isola o tríceps.'),
  ('e134', 'Tríceps unilateral na polia', 'Single-Arm Pushdown', 'Tríceps', 'isolado', 'iniciante', 'forca_hipertrofia', 'academia', 'Polia', 'academia', 4, 'Tríceps na polia um braço por vez, pegada supinada. Corrige diferenças entre os lados.'),
  ('e135', 'Tríceps francês', 'Overhead Triceps Extension', 'Tríceps', 'isolado', 'intermediario', 'forca_hipertrofia', 'casa', 'Halteres', 'casa_com', 4, 'Halter acima da cabeça, flexione os cotovelos descendo o peso atrás da nuca e estenda. Cotovelos apontando para cima.'),
  ('e136', 'Rosca 21', '21s Curl', 'Bíceps', 'isolado', 'intermediario', 'forca_hipertrofia', 'casa', 'Barra / Halteres', 'casa_com', 4, '7 repetições só na metade de baixo, 7 só na de cima e 7 completas, sem descanso. Técnica de intensidade para o bíceps.'),
  ('e137', 'Rosca de punho', 'Wrist Curl', 'Antebraços', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Halteres / Barra', 'casa_com', 4, 'Antebraços apoiados, flexione só os punhos elevando o peso e desça. Isola o antebraço.'),
  ('e138', 'Rosca de punho invertida', 'Reverse Wrist Curl', 'Antebraços', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Halteres / Barra', 'casa_com', 4, 'Antebraços apoiados e palmas para baixo, estenda só os punhos elevando o peso e desça. Trabalha a parte de cima do antebraço (extensores), pouco treinada.'),
  ('e139', 'Rolo de punho', 'Wrist Roller', 'Antebraços', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Rolo de punho', 'casa_com', 4, 'Com os braços à frente, enrole uma corda com peso num bastão girando só os punhos e desenrole devagar. Queima o antebraço inteiro rapidamente.'),
  ('e140', 'Pegada estática (farmer hold)', 'Farmer Hold', 'Antebraços, pegada', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Halteres / Kettlebell', 'casa_com', 4, 'Segure halteres ou kettlebells pesados parado, em pé e com o tronco ereto, pelo máximo de tempo. Treina a força de pegada de forma bem direta.'),
  ('e141', 'Agachamento hack', 'Hack Squat', 'Quadríceps, glúteos', 'agachar', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 4, 'Na máquina inclinada, agache com as costas apoiadas e empurre de volta. Guiado, bom para focar quadríceps com segurança.'),
  ('e142', 'Agachamento sissy', 'Sissy Squat', 'Quadríceps', 'agachar', 'avancado', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 4, 'Incline o tronco para trás flexionando só os joelhos à frente, segurando num apoio. Isola o quadríceps; avançado.'),
  ('e143', 'Avanço com salto', 'Jump Lunge', 'Pernas (cardio/potência)', 'agachar', 'intermediario', 'pliometrico', 'nenhum', 'Peso corporal', 'casa_sem', 4, 'Afundo em que você troca as pernas no ar com um salto. Aumenta intensidade e gasto calórico; mais avançado.'),
  ('e144', 'Thruster (agachamento + desenvolvimento)', 'Thruster', 'Corpo inteiro', 'cardio', 'avancado', 'cardio', 'casa', 'Halteres / Barra', 'casa_com', 4, 'Agache e, ao subir, empurre o peso acima da cabeça num só movimento. Trabalha pernas e ombros e eleva muito o cardio.'),
  ('e145', 'Agachamento unilateral (pistol)', 'Pistol Squat', 'Quadríceps, glúteos, equilíbrio', 'agachar', 'avancado', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 4, 'Agachamento numa perna só, a outra estendida à frente. Movimento avançado de força e equilíbrio; pode segurar num apoio para aprender.'),
  ('e146', 'Prancha com toque no ombro', 'Shoulder Tap Plank', 'Core, ombros', 'core', 'intermediario', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 4, 'Em prancha alta, toque alternadamente a mão no ombro oposto sem balançar o quadril. Trabalha estabilidade.'),
  ('e147', 'Bird dog (perdigueiro)', 'Bird Dog', 'Core, lombar', 'core', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 4, 'De quatro apoios, estenda braço e perna opostos mantendo o tronco estável, e troque. Ótimo para estabilidade da coluna.'),
  ('e148', 'Inseto morto (dead bug)', 'Dead Bug', 'Core, estabilidade', 'core', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 4, 'Deitado, braços e pernas para cima; estenda braço e perna opostos mantendo a lombar no chão, e troque. Ótimo para estabilidade.'),
  ('e149', 'Abdominal bicicleta', 'Bicycle Crunch', 'Abdômen (reto e oblíquos)', 'core', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 4, 'Deitado, leve o cotovelo ao joelho oposto alternando, como pedalar. Movimento controlado, sem puxar o pescoço.'),
  ('e150', 'Corrida no lugar (joelho alto)', 'High Knees', 'Cardio, core', 'cardio', 'iniciante', 'cardio', 'nenhum', 'Peso corporal', 'casa_sem', 4, 'Corra parado elevando os joelhos à altura do quadril, rápido. Aquece e eleva a frequência cardíaca.'),
  ('e151', 'Patinador (skater)', 'Skater Jumps', 'Pernas, cardio, equilíbrio', 'cardio', 'intermediario', 'pliometrico', 'nenhum', 'Peso corporal', 'casa_sem', 4, 'Salte lateralmente de uma perna para a outra, como um patinador. Trabalha glúteos e equilíbrio com cardio.'),
  ('e152', 'Agachamento sumô', 'Sumo Squat', 'Quadríceps, glúteos, adutores', 'agachar', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal / Halter', 'casa_sem', 4, 'Agachamento com os pés bem afastados e pontas para fora. Foca mais glúteos e parte interna da coxa. Pode segurar um halter.'),
  ('e153', 'Elevação pélvica na máquina', 'Machine Hip Thrust', 'Glúteos', 'dobradica_quadril', 'iniciante', 'forca_hipertrofia', 'academia', 'Máquina', 'academia', 4, 'Hip thrust em máquina específica. Carga estável e fácil de progredir; isola glúteos.'),
  ('e154', 'Remada cavalinho (T-bar)', 'T-Bar Row', 'Costas', 'puxar', 'intermediario', 'forca_hipertrofia', 'academia', 'Máquina / Barra', 'academia', 4, 'Tronco inclinado, puxe a barra em T em direção ao abdômen apertando as costas e desça. Boa para espessura de dorso.'),
  ('e155', 'Desenvolvimento militar', 'Military Press', 'Ombros, tríceps', 'empurrar', 'intermediario', 'forca_hipertrofia', 'academia', 'Barra', 'academia', 4, 'Desenvolvimento em pé com barra, partindo da altura do peito até acima da cabeça. Core firme, sem arquear demais.'),
  ('e156', 'Flexão inclinada (mãos elevadas)', 'Incline Push-Up', 'Peito, tríceps', 'empurrar', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 4, 'Flexão com as mãos apoiadas num banco/parede. Versão mais fácil — ideal para quem está começando.'),
  ('e157', 'Flexão na parede', 'Wall Push-Up', 'Peito, tríceps', 'empurrar', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 4, 'Flexão em pé contra a parede. A regressão mais acessível, boa para iniciantes absolutos ou reabilitação.'),
  ('e158', 'Panturrilha sentado', 'Seated Calf Raise', 'Panturrilhas (sóleo)', 'isolado', 'iniciante', 'forca_hipertrofia', 'casa', 'Halteres ou anilha sobre os joelhos', 'casa_com', 4, 'Sentado, com halteres ou uma anilha apoiados sobre os joelhos, eleve os calcanhares e desça com amplitude total. Foca o sóleo (parte profunda da panturrilha), que só ativa com o joelho dobrado. Na academia, a máquina de panturrilha sentado faz o mesmo.'),
  ('e159', 'Abdominal remador', 'Sit-Up', 'Abdômen', 'core', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 4, 'Deitado, suba o tronco todo até sentar e desça controlando. Mais amplo que o crunch; cuidado para não forçar a lombar.'),
  ('e160', 'Afundo reverso', 'Reverse Lunge', 'Quadríceps, glúteos', 'agachar', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 4, 'Em vez de passar à frente, dê o passo para trás e desça. Mais amigável aos joelhos que o afundo tradicional.'),
  ('e161', 'Ponte unilateral de glúteo', 'Single-Leg Glute Bridge', 'Glúteos', 'dobradica_quadril', 'iniciante', 'forca_hipertrofia', 'nenhum', 'Peso corporal', 'casa_sem', 4, 'Ponte de glúteo com uma perna estendida no ar. Aumenta a dificuldade e corrige diferenças entre os lados.'),
  ('e162', 'Remada com elástico', 'Band Row', 'Costas, bíceps', 'puxar', 'iniciante', 'forca_hipertrofia', 'casa', 'Elástico', 'casa_com', 4, 'Prenda o elástico à frente e puxe em direção ao abdômen apertando as costas. Alternativa barata e portátil para costas em casa.'),
  ('e163', 'Agachamento com salto', 'Jump Squat', 'Pernas (potência/cardio)', 'agachar', 'intermediario', 'pliometrico', 'nenhum', 'Peso corporal', 'casa_sem', 4, 'Agachamento explosivo terminando num salto, aterrissando suave. Desenvolve potência e eleva o gasto calórico; mais avançado.')
